r=r'''.libPaths(c('LIB','OLD/trajectory_dependencies_v1/R_project_library_v1','OLD/irGSEA_dependencies_v1/R_project_library_v1',.libPaths()));library(monocle);library(Matrix)
ns<-asNamespace('monocle');changed<-c()
for(nm in ls(ns,all.names=TRUE)){f<-get(nm,envir=ns);if(!is.function(f))next;txt<-paste(deparse(f),collapse='\n');if(grepl('neimode',txt,fixed=TRUE)||grepl('nei(',txt,fixed=TRUE)){
 writeLines(txt,paste0('OUTPUT/',nm,'_original.R'));txt<-gsub('graph.dfs(', 'igraph::dfs(',txt,fixed=TRUE);txt<-gsub('if (class(projection) != \"matrix\")','if (!is.matrix(projection))',txt,fixed=TRUE);txt<-gsub('neimode =','mode =',txt,fixed=TRUE);txt<-gsub('nei(','.nei(',txt,fixed=TRUE);txt<-gsub('father = TRUE','parent = TRUE',txt,fixed=TRUE);txt<-gsub('$father','$parent',txt,fixed=TRUE);f2<-eval(parse(text=txt),envir=ns);environment(f2)<-environment(f);assignInNamespace(nm,f2,ns='monocle');writeLines(txt,paste0('OUTPUT/',nm,'_patched.R'));changed<-c(changed,nm)}}
writeLines(changed,'OUTPUT/API_compatibility_patched_functions.txt')
src<-'OLD/F3_DDRTree_unrooted_v1/GSE244832';cds<-readRDS(file.path(src,'DDRTree_unrooted.rds'));keep<-tolower(as.character(pData(cds)$disease_comparison_eligible))=='true';cds<-cds[,keep];set.seed(0);cds<-reduceDimension(cds,max_components=2,reduction_method='DDRTree',norm_method='log',pseudo_expr=1,relative_expr=TRUE,verbose=FALSE);saveRDS(cds,'OUTPUT/core_unrooted_checkpoint.rds');z<-readRDS('CURRENT/F3_F5_ordered_trajectory_fixed_python_v2/F3/CytoTRACE_core.rds');cyto<-z$CytoTRACE;cds<-orderCells(cds);pData(cds)$CytoTRACE<-cyto[rownames(pData(cds))];stopifnot(all(is.finite(pData(cds)$CytoTRACE)));dm<-aggregate(CytoTRACE~State+donor,data=pData(cds),mean);state<-aggregate(CytoTRACE~State,data=dm,mean);root<-state$State[which.max(state$CytoTRACE)];write.table(state,'OUTPUT/root_selection_equal_donor.tsv',sep='\t',quote=FALSE,row.names=FALSE);cds<-orderCells(cds,root_state=root);write.table(pData(cds),'OUTPUT/ordered_cell_metadata.tsv',sep='\t',quote=FALSE,col.names=NA);write.table(table(pData(cds)$State,pData(cds)$donor),'OUTPUT/state_donor_counts.tsv',sep='\t',quote=FALSE);saveRDS(cds,'OUTPUT/ordered_checkpoint.rds');cds<-estimateDispersions(cds);genes<-rownames(fData(cds))[fData(cds)$use_for_ordering];de<-differentialGeneTest(cds[genes,],fullModelFormulaStr='~sm.ns(Pseudotime,df=3)',reducedModelFormulaStr='~1',cores=4);write.table(de,'OUTPUT/pseudotime_dynamic_genes.tsv',sep='\t',quote=FALSE,col.names=NA);writeLines(capture.output(sessionInfo()),'OUTPUT/sessionInfo.txt');writeLines('completed','OUTPUT/COMPLETE.txt')
'''.replace('CURRENT',str(P)).replace('LIB',str(P/'R_library')).replace('OLD',str(D)).replace('OUTPUT',str(O))
